$taskArchive = 'experiments/preparation-20261012-bc-loop-01'
$taskRules = @('src/skills/learning-assessment/SKILL.md','src/skills/learning-assessment/references/product-review.md')
foreach ($taskSuffix in $taskRules) { $taskSource = Join-Path '../../personal-learning-suite' $taskSuffix; $taskDest = Join-Path (Join-Path $taskArchive 'environment/rules-snapshot') $taskSuffix; New-Item -ItemType Directory -Force -Path (Split-Path -Parent $taskDest) | Out-Null; Copy-Item -LiteralPath $taskSource -Destination $taskDest }
$taskChecks = $taskRules | ForEach-Object { [pscustomobject]@{source=$_;sha256=(Get-FileHash -LiteralPath (Join-Path '../../personal-learning-suite' $_) -Algorithm SHA256).Hash.ToLower();read_by='AG3 receipt'} }
$taskChecks | ConvertTo-Json | Set-Content -LiteralPath (Join-Path $taskArchive 'environment/ag3-rules-read-and-snapshot.json') -Encoding utf8
